var root = Path.Combine(Path.GetTempPath(), "Shige-platform-tests", Guid.NewGuid().ToString("N")); Directory.CreateDirectory(root); var source = Path.Combine(root, "source"); var dest = Path.Combine(root, "destination"); Directory.CreateDirectory(source); Directory.CreateDirectory(dest); var f = Path.Combine(source, "sample.txt"); File.WriteAllText(f, "original"); File.WriteAllText(Path.Combine(dest, "sample.txt"), "existing");
