var copied = await ShellFiles.TransferAsync([f], dest, false); Check(copied.Completed == 1 && File.ReadAllText(Path.Combine(dest, "sample.txt")) == "existing" && File.ReadAllText(Path.Combine(dest, "sample (2).txt")) == "original", "copy collision preserves existing");
